_ACTIONS_DEPRECATION_SINCE = "2026-05-14"
_ACTIONS_SUNSET_DATE = "2026-06-15"
_ACTIONS_SUNSET_HTTP_DATE = "Mon, 15 Jun 2026 00:00:00 GMT"
