_ADVANCE_LIFECYCLE_VALID_TARGETS = frozenset({"paper_owner", "live_owner", "retired"})

# Roles required for live_owner target (more privileged)
_ADVANCE_LIFECYCLE_LIVE_ROLES = frozenset({"approver", "admin"})


@app.post("/bff/personas/{persona_id}/actions/{action_id}", status_code=202)
async def bff_persona_action(
    persona_id: str,
    action_id: str,
    payload: Dict[str, Any] = Body(default_factory=dict),
    authorization: Optional[str] = Header(default=None),
    idempotency_key: Optional[str] = Header(default=None, alias="Idempotency-Key"),
    x_idempotency_key: Optional[str] = Header(default=None, alias="X-Idempotency-Key"),
):
    """BFF: persona action — routes through command/precondition machinery.

    AdvanceLifecycle is registered (P0-1) and returns 202. All other action_ids
    still return 410 until individually registered.
    """
    # P0-1: AdvanceLifecycle registered and active
    if action_id == "AdvanceLifecycle":
        identity = _extract_identity(authorization)
        _require_operator_role(identity)
        _reject_body_idempotency_key(payload)
        resolved_key = _resolve_final_idempotency_key(idempotency_key, x_idempotency_key)

        target_state = str(payload.get("target_state") or "").strip()
        if target_state not in _ADVANCE_LIFECYCLE_VALID_TARGETS:
            raise _bff_error(
                422,
                ErrorCode.VALIDATION_FAILED,
                "target_state is required and must be paper_owner, live_owner, or retired",
                f"Got {target_state!r}; allowed: {sorted(_ADVANCE_LIFECYCLE_VALID_TARGETS)}",
                precondition_failed="target_state",
            )

        if target_state == "live_owner" and not _ADVANCE_LIFECYCLE_LIVE_ROLES.intersection(identity.roles):
            raise _bff_error(
                403,
                ErrorCode.FORBIDDEN,
                "Advancing to live_owner requires approver or admin role",
                "Operator does not hold live_owner_approver role",
                precondition_failed="role_check",
            )

        confirm_token = str(payload.get("confirm_token") or "").strip()
        if not confirm_token:
            raise _bff_error(
                422,
                ErrorCode.VALIDATION_FAILED,
                "confirm_token is required for AdvanceLifecycle",
                "Provide a valid confirm_token in the request body",
                precondition_failed="confirm_token",
            )

        _ensure_persona_exists(persona_id)

        enriched_payload = {**payload, "persona_id": persona_id}
        return _strategy_persona_action_command(
            entity_type=ObjectType.PERSONA,
            entity_id=persona_id,
            action_id=action_id,
            resolved_key=resolved_key,
            identity=identity,
            payload=enriched_payload,
            command_type=CommandType.ADVANCE_LIFECYCLE,
        )

    return _deprecated_bff_path_response(
        route="/bff/personas/{persona_id}/actions/{action_id}",
        replacement="/bff/actions/persona/{persona_id}/{action_id}",
    )
    identity = _extract_identity(authorization)  # noqa: F841 — unreachable; preserved for future de-deprecation
    _require_read_role(identity)
    _reject_body_idempotency_key(payload)
    resolved_key = _resolve_final_idempotency_key(idempotency_key, x_idempotency_key)
    _ensure_persona_exists(persona_id)
    return _strategy_persona_action_command(
        entity_type=ObjectType.PERSONA,
        entity_id=persona_id,
        action_id=action_id,
        resolved_key=resolved_key,
        identity=identity,
        payload=payload,
        command_type=CommandType.PERSONA_ACTION,
    )


@app.post("/bff/personas/{persona_id}/test-prompt", status_code=202)
async def bff_persona_test_prompt(
    persona_id: str,
    payload: Dict[str, Any] = Body(default_factory=dict),
    authorization: Optional[str] = Header(default=None),
    idempotency_key: Optional[str] = Header(default=None, alias="Idempotency-Key"),
    x_idempotency_key: Optional[str] = Header(default=None, alias="X-Idempotency-Key"),
):
    """BFF: send a test prompt to a persona; returns a stub trial handle."""
    identity = _extract_identity(authorization)
    _require_read_role(identity)
    _reject_body_idempotency_key(payload)
    resolved_key = _resolve_final_idempotency_key(idempotency_key, x_idempotency_key)
    _ensure_persona_exists(persona_id)
    request_hash = _stable_json_hash(
        {"route": "POST /bff/personas/{id}/test-prompt", "id": persona_id, "payload": payload}
    )
    cached = _strategy_persona_idempotency_check(resolved_key, request_hash)
    if cached is not None:
        return cached
    prompt = str(payload.get("prompt") or "").strip()
    if not prompt:
        raise _bff_error(
            422, ErrorCode.VALIDATION_FAILED, "prompt is required",
            "Persona test-prompt requires a non-empty prompt",
            precondition_failed="prompt",
        )
    snapshot_at = utc_now()
    trial_id = f"prompt-{persona_id}-{uuid.uuid4().hex[:8]}"
    result = {
        "data": {
            "trial_id": trial_id,
            "persona_id": persona_id,
            "status": "queued",
            "queued_at": snapshot_at,
            "prompt": prompt,
            "params": payload.get("params") or {},
            "requested_by": identity.operator_id,
        },
        "meta": {"snapshot_at": snapshot_at},
    }
    _STRATEGY_PERSONA_BFF_IDEMPOTENCY[resolved_key] = {"request_hash": request_hash, "result": result}
    return result


# ---------------- Platform helpers ----------------

@app.get("/bff/search")
async def bff_search(
    q: str = Query(default=""),
    types: Optional[str] = Query(default=None),
    page_size: int = Query(default=20, ge=1, le=100),
    limit: Optional[int] = Query(default=None, ge=1, le=100),
    page_token: Optional[str] = Query(default=None),
    authorization: Optional[str] = Header(default=None),
):
    """BFF: cross-entity search across strategies, personas, and capital pools.

    Accepts page_token (opaque offset cursor) and page_size for cursor-style
    pagination.  A non-null next_page_token in the response indicates more
    results are available; pass it back as page_token on the next request.

    `limit` is a backward-compatible alias for `page_size`; when both are
    provided, `limit` takes precedence so legacy callers are not silently
    truncated.
    """
    identity = _extract_identity(authorization)
    _require_read_role(identity)
    effective_page_size = limit if limit is not None else page_size
    snapshot_at = utc_now()
    needle = q.strip().lower()
    requested_types: Optional[set[str]] = None
    if types:
        requested_types = {t.strip().lower() for t in types.split(",") if t.strip()}

    results: List[Dict[str, Any]] = []

    def _match(text: Any) -> bool:
        if not needle:
            return True
        return needle in str(text or "").lower()

    if not requested_types or "strategy" in requested_types:
        for summary in _list_strategy_summaries():
            strategy_id = str(summary.get("strategy_id") or "")
            name = summary.get("title") or strategy_id
            if _match(strategy_id) or _match(name):
                results.append({
                    "id": strategy_id,
                    "type": "strategy",
                    "name": str(name),
                    "state": _normalize_lifecycle_state(summary.get("lifecycle_state")),
                    "owner": str(summary.get("owner") or "pantheon-bff"),
                    "risk": "medium",
                    "updatedAt": summary.get("last_modified_at") or snapshot_at,
                })

    if not requested_types or "persona" in requested_types:
        for raw in _list_persona_records():
            persona_id = str(raw.get("persona_id") or raw.get("id") or "")
            name = raw.get("name") or persona_id
            if _match(persona_id) or _match(name):
                metadata = raw.get("metadata") if isinstance(raw.get("metadata"), dict) else {}
                results.append({
                    "id": persona_id,
                    "type": "persona",
                    "name": str(name),
                    "state": _normalize_lifecycle_state(raw.get("lifecycle_state")),
                    "owner": str(metadata.get("owner") or raw.get("owner") or "pantheon-bff"),
                    "risk": _normalize_risk_level(metadata.get("risk_level")),
                    "updatedAt": raw.get("updated_at") or raw.get("created_at") or snapshot_at,
                })

    if not requested_types or "capital_pool" in requested_types or "capitalPool" in requested_types:
        for pool in (read_store.list_capital_pools() or []):
            pool_id = str(pool.get("id") or pool.get("pool_id") or "")
            name = pool.get("name") or pool_id
            if _match(pool_id) or _match(name):
                results.append({
                    "id": pool_id,
                    "type": "capital_pool",
                    "name": str(name),
                    "state": _normalize_lifecycle_state(pool.get("status")),
                    "owner": str(pool.get("owner") or "pantheon-bff"),
                    "risk": _normalize_risk_level(pool.get("risk_level")),
                    "updatedAt": pool.get("updated_at") or pool.get("created_at") or snapshot_at,
                })

    page_items, next_page_token = _page_slice(results, page_token, effective_page_size)
    return {
        "data": page_items,
        "items": page_items,
        "page_info": {"next_page_token": next_page_token, "total": len(results), "returned": len(page_items)},
        "meta": _read_surface_meta(
            "personas", "search",
            snapshot_at=snapshot_at, total=len(page_items),
        ),
    }


