def _sem_local_records(dataset: str) -> tuple[str, List[Dict[str, Any]]]:
    data = getattr(read_store, "_data", {})
    raw = data.get(dataset) if isinstance(data, dict) else None
    if isinstance(raw, dict):
        return ("local_snapshot" if raw else "missing", [dict(item) for item in raw.values() if isinstance(item, dict)])
    if isinstance(raw, list):
        return ("local_snapshot" if raw else "missing", [dict(item) for item in raw if isinstance(item, dict)])
    return "missing", []


def _sem_read_records(dataset: str) -> tuple[str, List[Dict[str, Any]]]:
    reader = getattr(read_store, "_read_dataset_records", None)
    source_fn = getattr(read_store, "dataset_source", None)
    if not callable(reader):
        return _sem_local_records(dataset)

    records = [dict(item) for item in reader(dataset) if isinstance(item, dict)]
    source = source_fn(dataset) if callable(source_fn) else ("local_snapshot" if records else "missing")
    if source == "missing" and records:
        source = "local_snapshot"
    return source, records


def _sem_list_payload(dataset: str, surface_key: str, *, filter_mode: Optional[str] = None) -> Dict[str, Any]:
    source, records = _sem_read_records(dataset)
    if filter_mode:
        records = [record for record in records if str(record.get("mode") or "") == filter_mode]
    snapshot_at = utc_now()
    surface = _dataset_surface_status(
        dataset,
        snapshot_at=snapshot_at,
        source=source,
        has_data=(source != "missing"),
    )
    meta = _read_surface_meta(
        dataset,
        surface_key,
        snapshot_at=snapshot_at,
        total=len(records),
        surface=surface,
    )
    return {"data": records, "items": records, "page_info": {"next_page_token": None}, "meta": meta}


def _sem_inbox_records(dataset: str, inbox_type: str) -> tuple[str, List[Dict[str, Any]]]:
    source, records = _sem_read_records(dataset)
    typed_records: List[Dict[str, Any]] = []
    for record in records:
        item = dict(record)
        item.setdefault("inboxType", inbox_type)
        item.setdefault("sourceDataset", dataset)
        typed_records.append(item)
    return source, typed_records


def _sem_inbox_sort_value(record: Dict[str, Any]) -> str:
    for field in ("updatedAt", "updated_at", "createdAt", "created_at"):
        value = record.get(field)
        if value:
            return str(value)
    return str(record.get("id") or record.get("signal_id") or record.get("ticket_id") or "")


def _sem_agora_inbox_payload() -> Dict[str, Any]:
    snapshot_at = utc_now()
    datasets = [
        ("insight_cards", "insight", "agora_inbox_insights"),
        ("agora_signals", "signal", "agora_inbox_signals"),
        ("research_tickets", "research_task", "agora_inbox_research_tasks"),
    ]
    records: List[Dict[str, Any]] = []
    sources: Dict[str, str] = {}
    counts: Dict[str, int] = {}
    surfaces: Dict[str, Dict[str, Any]] = {}

    for dataset, inbox_type, surface_key in datasets:
        source, typed_records = _sem_inbox_records(dataset, inbox_type)
        sources[dataset] = source
        counts[inbox_type] = len(typed_records)
        records.extend(typed_records)
        surfaces[surface_key] = _dataset_surface_status(
            dataset,
            snapshot_at=snapshot_at,
            source=source,
            has_data=(source != "missing"),
        )

    records.sort(key=_sem_inbox_sort_value, reverse=True)
    primary_surface = _dataset_surface_status(
        "insight_cards",
        snapshot_at=snapshot_at,
        source=sources.get("insight_cards"),
        has_data=(sources.get("insight_cards") != "missing"),
    )
    meta = _read_surface_meta(
        "insight_cards",
        "agora_inbox",
        snapshot_at=snapshot_at,
        total=len(records),
        surface=primary_surface,
    )
    meta["surfaces"].update(surfaces)
    meta["composition"] = {
        "datasets": [dataset for dataset, _, _ in datasets],
        "itemCounts": counts,
    }
    return {"data": records, "items": records, "page_info": {"next_page_token": None}, "meta": meta}


